package text

import "testing"

// Normalize is documented to be idempotent: Normalize(Normalize(s)) == Normalize(s).
func FuzzNormalize(f *testing.F) {
	f.Add("  Hello  ")
	f.Add("")
	f.Fuzz(func(t *testing.T, s string) {
		once := Normalize(s)
		twice := Normalize(once)
		if once != twice { // idempotence: applying again must change nothing
			t.Errorf("not idempotent: Normalize(%q)=%q but Normalize again=%q", s, once, twice)
		}
	})
}

