package solution

import (
	"strings"
	"unicode/utf8"
)

func IsPalindrome(s string) bool {
	s = strings.ToLower(s)             // case-insensitive comparison
	rs := []rune(s)                    // decode to runes so multibyte chars work
	for i, j := 0, len(rs)-1; i < j; i, j = i+1, j-1 {
		if rs[i] != rs[j] {            // compare from both ends inward
			return false
		}
	}
	_ = utf8.RuneCountInString         // ensures we reasoned about runes, not bytes
	return true
}

// reverse is a rune-correct helper used by the fuzz property.
func reverse(s string) string {
	rs := []rune(s)
	for i, j := 0, len(rs)-1; i < j; i, j = i+1, j-1 {
		rs[i], rs[j] = rs[j], rs[i]
	}
	return string(rs)
}

codeLab.testHarness:
package solution

import "testing"

// Table-driven unit test pins known behavior.
func TestIsPalindrome(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"empty", "", true},
		{"single", "x", true},
		{"simple", "level", true},
		{"mixed case", "RaceCar", true},
		{"not", "hello", false},
		{"unicode", "éé", true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := IsPalindrome(tc.in); got != tc.want {
				t.Errorf("IsPalindrome(%q)=%v want %v", tc.in, got, tc.want)
			}
		})
	}
}

// Fuzz test asserts a property: reversing the input must not change the result.
func FuzzIsPalindrome(f *testing.F) {
	f.Add("level")
	f.Add("")
	f.Add("RaceCar")
	f.Fuzz(func(t *testing.T, s string) {
		if IsPalindrome(s) != IsPalindrome(reverse(s)) {
			t.Errorf("property broken for %q", s)
		}
	})
}

