func FirstWord(s string) string {
	fields := strings.Fields(s)
	if len(fields) == 0 { // handle empty / whitespace-only input
		return ""
	}
	return fields[0]
}

func FuzzAtoi(f *testing.F) {
	f.Add("123")
	f.Add("-7")
	f.Add("")
	f.Add("+0")
	f.Add("99999999999999999999") // overflow case
	f.Fuzz(func(t *testing.T, s string) {
		got, gotErr := Atoi(s)
		want, wantErr := strconv.Atoi(s)
		// Both must agree on whether parsing succeeded.
		if (gotErr == nil) != (wantErr == nil) {
			t.Fatalf("Atoi(%q): error mismatch got=%v want=%v", s, gotErr, wantErr)
		}
		// On success, the values must match.
		if gotErr == nil && got != want {
			t.Errorf("Atoi(%q)=%d want %d", s, got, want)
		}
	})
}
